-- Create this file with scripts/integer-fixtures.py.
module Fixtures (cases) where

import Factorise (Case (..))

-- | The fixed cases of a backend and profile, sized so that one pass takes about half a second.
cases :: String -> String -> Maybe [Case]
cases backend profile
  | backend == "native" = lookup profile [("O0", casesNativeO0), ("Os", casesNativeOs), ("O1", casesNativeO1), ("O2", casesNativeO2)]
  | backend == "llvm" = lookup profile [("O0", casesLlvmO0), ("Os", casesLlvmOs), ("O1", casesLlvmO1), ("O2", casesLlvmO2)]
  | backend == "wasm" = lookup profile [("O0", casesWasmO0), ("Os", casesWasmOs), ("O1", casesWasmO1), ("O2", casesWasmO2)]
  | otherwise = Nothing

